import { instant } from '@absoluteui/core';
import { FileManager, type FileEntry, type FileManagerProvider } from '@absoluteui/components/file-manager';

// An in-memory provider; a real one calls your API and passes request.signal to fetch.
const entries: FileEntry[] = [
  { id: 'contracts', name: 'Contracts', kind: 'folder', parentId: null },
  { id: 'policies', name: 'Policies', kind: 'folder', parentId: null, hasChildren: false },
  { id: 'offer', name: 'Offer letter.txt', kind: 'file', size: 2048, mimeType: 'text/plain', modified: instant(Date.UTC(2026, 2, 3, 9, 30)), parentId: 'contracts' },
];
let next = 1;
const provider: FileManagerProvider = {
  list: async (folderId) => entries.filter((e) => e.parentId === folderId),
  createFolder: async (parentId, name) => {
    const entry: FileEntry = { id: `folder-${String(next++)}`, name, kind: 'folder', parentId };
    entries.push(entry);
    return entry;
  },
  rename: async (entry, name) => ({ ...entry, name }),
  move: async (moved, targetFolderId) => moved.map((e) => ({ ...e, parentId: targetFolderId })),
  delete: async () => {},
  upload: async (folderId, file, request) => {
    request.onProgress(file.size, file.size);
    return { id: `file-${String(next++)}`, name: file.name, kind: 'file', size: file.size, mimeType: file.type, parentId: folderId };
  },
  read: async () => 'Dear Ada, we are pleased to offer you the position.',
};

const host = document.createElement('div');
document.body.append(host);
const files = FileManager.create(host, { label: 'Employee documents', provider, root: { id: null, label: 'Documents' }, maxFileSize: 10_000_000 });
host.addEventListener('aui-navigate', () => {
  host.dataset.folder = files.currentFolderId ?? 'root';
});

import { FileManager, type FileManagerErrorDetail, type FileManagerOpenDetail, type FileManagerProvider } from '@absoluteui/components/file-manager';

declare const provider: FileManagerProvider;

const host = document.createElement('div');
document.body.append(host);
FileManager.create(host, { label: 'Scans', provider, view: 'grid', readOnly: true, accept: ['image/*', '.pdf'] });
host.addEventListener('aui-open', (event) => {
  const { entry } = (event as CustomEvent<FileManagerOpenDetail>).detail;
  // Handle PDFs yourself; images still open in the built-in Image Viewer.
  if (entry.mimeType === 'application/pdf') {
    event.preventDefault();
    window.open(`/documents/${encodeURIComponent(entry.id)}`, '_blank', 'noopener');
  }
});
host.addEventListener('aui-error', (event) => {
  const { operation } = (event as CustomEvent<FileManagerErrorDetail>).detail;
  host.dataset.lastError = operation;
});

import { FileManager, type FileManagerProvider } from '@absoluteui/components/file-manager';

declare const provider: FileManagerProvider;

const host = document.createElement('div');
document.body.append(host);
FileManager.create(host, {
  label: 'Reports',
  provider,
  showFolderPane: false,
  height: '24rem',
  preview: async (entry, { signal }) => {
    if (!entry.name.endsWith('.csv') || !provider.read) return null;
    const text = await provider.read(entry, { signal });
    const pre = document.createElement('pre');
    pre.textContent = text.split('\n').slice(0, 20).join('\n');
    return pre;
  },
});
